    doc.setFont("Emirates", "bold");
    doc.setFontSize(11);
    doc.setTextColor("#0C3C74");
    doc.text("Service Report", pageWidth - 60, 12);
    doc.setFontSize(11);

    doc.setTextColor(255, 0, 0); // Red color for SRN number
